<script setup lang="ts">
import { onMounted, ref } from 'vue'
const plan=ref({enabled:false,frequency:'daily',hour:3,minute:0,weekday:0,keep:7,local_dir:'',github_repo:''})
const runs=ref<any[]>([])
const remote=ref<any[]>([])
const passwordConfigured=ref(false)
const tokenConfigured=ref(false)
const status=ref('')
const busy=ref(false)
async function json(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const value=await r.json();if(!r.ok)throw new Error(value.detail||`HTTP ${r.status}`);return value}
function statusName(value:string,target:'local'|'github'){return ({success:'成功',disabled:'未启用',failed:'失败',retention_failed:target==='local'?'新备份成功，清理旧份失败':'上传成功，清理旧份失败',missing_token:'缺少 token'} as Record<string,string>)[value]||value}
async function load(){try{const data=await json('/api/system/backup-plan');plan.value=data.plan;runs.value=data.runs;passwordConfigured.value=data.password_configured;tokenConfigured.value=data.github_token_configured}catch(e){status.value=String(e)}}
async function save(){busy.value=true;try{await json('/api/system/backup-plan','PUT',plan.value);status.value='备份计划已保存';await load()}catch(e){status.value=String(e)}finally{busy.value=false}}
async function run(){busy.value=true;try{const result=await json('/api/system/backup-plan/run','POST');status.value=`本地：${statusName(result.local,'local')}；GitHub：${statusName(result.github,'github')}`;await load()}catch(e){status.value=String(e)}finally{busy.value=false}}
async function list(){try{remote.value=await json('/api/system/backup-plan/github')}catch(e){status.value=String(e)}}
async function download(name:string){const r=await fetch(`/api/system/backup-plan/github/${encodeURIComponent(name)}`);if(!r.ok){status.value='下载失败';return}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.value='已下载加密备份；请用上方恢复入口验证密码并确认替换。'}
onMounted(load)
</script>
<template><details class="v2-backup"><summary>同步目录与 GitHub 定时备份</summary><p>服务启动时补做错过的任务。密码与 GitHub token 仅从后端环境变量读取；当前状态：密码{{passwordConfigured?'已配置':'未配置'}}，token {{tokenConfigured?'已配置':'未配置'}}。</p><p>本地目录属于后端机器。GitHub 请使用与源码分开的私有仓库；删除旧文件不会清除 Git 历史容量。</p><label><input v-model="plan.enabled" type="checkbox"/>启用定时备份</label><div class="v2-grid"><label>频率<select v-model="plan.frequency"><option value="daily">每天</option><option value="weekly">每周</option></select></label><label>小时<input v-model.number="plan.hour" type="number" min="0" max="23"/></label><label>分钟<input v-model.number="plan.minute" type="number" min="0" max="59"/></label><label v-if="plan.frequency==='weekly'">星期<select v-model.number="plan.weekday"><option v-for="day in 7" :key="day" :value="day-1">{{['一','二','三','四','五','六','日'][day-1]}}</option></select></label><label>保留份数<input v-model.number="plan.keep" type="number" min="1" max="100"/></label><label>本地同步目录<input v-model="plan.local_dir" placeholder="D:\Backups\YOSAKI"/></label><label>私有 GitHub 仓库<input v-model="plan.github_repo" placeholder="owner/backup-repo"/></label></div><button :disabled="busy" @click="save">保存计划</button><button :disabled="busy" @click="run">立即备份</button><button @click="list">查看云端备份</button><div v-for="item in remote" :key="item.name">{{item.name}} <button @click="download(item.name)">下载以恢复</button></div><div v-for="item in runs" :key="item.id">{{item.started_at}} · 本地 {{statusName(item.local_status,'local')}} · GitHub {{statusName(item.github_status,'github')}}</div><p role="status">{{status}}</p></details></template>
<style scoped>.v2-backup{padding:12px;border:1px solid #716f83;border-radius:12px;margin:8px}.v2-backup summary{cursor:pointer}.v2-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin:10px 0}.v2-grid label{display:flex;flex-direction:column;gap:4px}.v2-grid input,.v2-grid select{width:100%;background:#242230;color:#f2eefb;border:1px solid #625a78;border-radius:6px;padding:6px}.v2-backup button{background:#373047;color:#f2ecff;border:1px solid #645a80;border-radius:7px;padding:7px 10px;margin:4px 8px 4px 0}.v2-backup button:disabled{opacity:.5;cursor:not-allowed}</style>
